#!/bin/sh
# Board side: the AI cluster's own int8 ceiling - the denominator a roofline needs.
#
# The probe is a pure-matrix QDQ graph (one int8 `MatMul` against a constant
# per-channel-symmetric weight, then a `DequantizeLinear`; nothing else), generated by
# `.local/onnx-baseline/make-ime-probe.py`. It is an instrument, not a model: it isolates what this
# board's AI cluster plus this provider deliver on matrix work, so a model's achieved rate can be
# read against something measured here instead of a quoted peak or another product's number.
#
# Three claims are separated, as everywhere in this project:
#
#   * the rate    - the vendor's own `onnxruntime_perf_test` with its published option set
#                   (`-r 10 -x 1 -S 1 -s -c 1 -I`), one row per (probe, thread count), repeated so
#                   the headline is a median of independent runs, plus a CPU-EP control row that
#                   prices what a silent fallback would look like;
#   * the claim   - ONNX Runtime's per-node profile (`-p`), parsed on the host with
#                   `ort-provider-census.py`: it names the provider of every one of the probe's six
#                   nodes. The `-C session.disable_cpu_ep_fallback|1` route is unusable here - this
#                   build's `perf_test` adds the CPU EP itself, so the flag is refused (measured
#                   again on 2026-09-22, matching the round-1 `cover-*` logs);
#   * the cluster - `spacemit-tcm-smi` sampled while a long run is in flight, naming that run's pid,
#                   plus the process's own thread set while it runs.
#
#   board-ime-probe.sh
#
# Env: ORT (package root), M (probe directory), OUT (output directory), REPS, ROUNDS, ENGAGE_REPS.
set -eu
ORT=${ORT:-/tmp/ort206}
M=${M:-/root/ime-probe}
OUT=${OUT:-/tmp/ime-probe-out}
REPS=${REPS:-10}
ROUNDS=${ROUNDS:-3}
ENGAGE_REPS=${ENGAGE_REPS:-2000}
PROBES=${PROBES:-1024 2048}
mkdir -p "$OUT"
export LD_LIBRARY_PATH="$ORT/lib"
perf="$ORT/bin/onnxruntime_perf_test"

state() {
    printf '== board state: %s\n' "$1"
    for c in 0 8; do
        printf '   cpu%-2s governor=%s cur_khz=%s max_khz=%s\n' "$c" \
            "$(cat /sys/devices/system/cpu/cpu$c/cpufreq/scaling_governor)" \
            "$(cat /sys/devices/system/cpu/cpu$c/cpufreq/scaling_cur_freq)" \
            "$(cat /sys/devices/system/cpu/cpu$c/cpufreq/cpuinfo_max_freq)"
    done
    printf '   temps_c: %s\n' "$(cat /sys/class/thermal/thermal_zone0/temp \
        /sys/class/thermal/thermal_zone3/temp 2>/dev/null | tr '\n' ' ')"
}

row() {
    tag=$1
    model=$2
    threads=$3
    shift 3
    if "$perf" "$model" -e spacemit -r "$REPS" -x 1 -S 1 -s -c 1 -I \
        -i "SPACEMIT_EP_INTRA_THREAD_NUM|$threads" "$@" > "$OUT/$tag.log" 2>&1; then
        printf '%-20s avg=%-18s p50=%-16s p90=%-16s first=%-16s sess=%s\n' "$tag" \
            "$(sed -n 's/^Average inference time cost total: \(.*\)$/\1/p' "$OUT/$tag.log" | tail -1)" \
            "$(sed -n 's/^P50 Latency: \(.*\)$/\1/p' "$OUT/$tag.log" | tail -1)" \
            "$(sed -n 's/^P90 Latency: \(.*\)$/\1/p' "$OUT/$tag.log" | tail -1)" \
            "$(sed -n 's/^First inference time cost: \(.*\)$/\1/p' "$OUT/$tag.log" | tail -1)" \
            "$(sed -n 's/^Session creation time cost: \(.*\)$/\1/p' "$OUT/$tag.log" | tail -1)"
    else
        printf '%-20s FAILED: %s\n' "$tag" "$(tail -2 "$OUT/$tag.log" | tr '\n' ' ')"
    fi
}

# `spacemit-tcm-smi`'s PID column names whatever id the AI thread registered with the driver - the
# process itself on some paths, a thread id on others. Match the workload by any of its thread ids.
tcm_lines() {
    pattern=$(ls /proc/"$1"/task 2>/dev/null | tr '\n' '|' | sed 's/|$//')
    [ -n "$pattern" ] || return 0
    spacemit-tcm-smi 2>/dev/null | grep -E " ($pattern) "
}

state before

printf '\n== the rate: vendor option set, one row per probe and thread count, %s rounds\n' "$ROUNDS"
r=1
while [ "$r" -le "$ROUNDS" ]; do
    for p in $PROBES; do
        for n in 1 2 4 8; do
            row "r${r}-p${p}-t${n}" "$M/ime-probe-${p}.onnx" "$n"
        done
    done
    r=$((r + 1))
done

printf '\n== the claim: per-node profile naming the provider of every node\n'
for p in $PROBES; do
    row "census-p${p}-t8" "$M/ime-probe-${p}.onnx" 8 -p "$OUT/census-p${p}.json"
done

printf '\n== the control: what a silent CPU-EP fallback would cost (X100, ORT pool 8)\n'
for p in $PROBES; do
    if "$perf" "$M/ime-probe-${p}.onnx" -e cpu -r 3 -x 8 -S 1 -s -c 1 -I \
        > "$OUT/cpu-p${p}-t8.log" 2>&1; then
        printf '%-20s avg=%s\n' "cpu-p${p}-t8" \
            "$(sed -n 's/^Average inference time cost total: \(.*\)$/\1/p' "$OUT/cpu-p${p}-t8.log" | tail -1)"
    else
        printf '%-20s FAILED: %s\n' "cpu-p${p}-t8" \
            "$(tail -2 "$OUT/cpu-p${p}-t8.log" | tr '\n' ' ')"
    fi
done

printf '\n== the cluster: a long run sampled while it is in flight\n'
"$perf" "$M/ime-probe-2048.onnx" -e spacemit -r "$ENGAGE_REPS" -x 1 -S 1 -c 1 -I \
    -i "SPACEMIT_EP_INTRA_THREAD_NUM|8" > "$OUT/engage.log" 2>&1 &
    # No `setsid`: it may fork, and `$!` would then name the wrapper instead of the workload.
pid=$!
i=0
max_threads=0
: > "$OUT/engage-tcm.txt"
: > "$OUT/engage-threads.txt"
while [ "$i" -lt 60 ]; do
    tcm_lines "$pid" >> "$OUT/engage-tcm.txt" || true
    kill -0 "$pid" 2>/dev/null || break
    if [ -d "/proc/$pid/task" ]; then
        n=$(ls /proc/"$pid"/task | wc -l)
        if [ "$n" -gt "$max_threads" ]; then
            max_threads=$n
            ps -L -o tid,comm,psr -p "$pid" > "$OUT/engage-threads.txt" 2>&1 || true
        fi
    fi
    sleep 0.2
    i=$((i + 1))
done
wait "$pid" || true
printf '   tcm lines naming pid %s: %s\n' "$pid" "$(wc -l < "$OUT/engage-tcm.txt")"
printf '   max threads seen during the run: %s (table in engage-threads.txt)\n' "$max_threads"
printf '   engage avg: %s\n' \
    "$(sed -n 's/^Average inference time cost total: \(.*\)$/\1/p' "$OUT/engage.log" | tail -1)"

printf '\n== the cluster per width: which blocks the pid holds at 1/2/4/8 threads\n'
for n in 1 2 4 8; do
    "$perf" "$M/ime-probe-2048.onnx" -e spacemit -r 400 -x 1 -S 1 -c 1 -I \
        -i "SPACEMIT_EP_INTRA_THREAD_NUM|$n" > "$OUT/tcm-p2048-t$n.log" 2>&1 &
    pid=$!
    blocks=
    i=0
    while [ "$i" -lt 25 ]; do
        sample=$(tcm_lines "$pid" | awk '{print $1}' | sort -u | tr '\n' ' ')
        [ -n "$sample" ] && blocks=$sample
        kill -0 "$pid" 2>/dev/null || break
        sleep 0.2
        i=$((i + 1))
    done
    wait "$pid" || true
    printf '   intra=%s blocks_held=%s count=%s\n' "$n" "$blocks" \
        "$(printf '%s' "$blocks" | wc -w)"
done

state after
printf '\n== artifacts in %s\n' "$OUT"
ls -l "$OUT" | tail -25
